                    $this->mc('Une nouvelle version d’API retire immédiatement un champ utilisé par des clients mobiles anciens. Quelle pratique réduit la rupture ?', 'Introduire une évolution compatible et une période de migration avec retrait annoncé', 'Retirer le champ sans mesurer les usages', 'Partager la base interne avec les clients', 'Désactiver les anciens clients sans préavis', 'Une transition versionnée ou rétrocompatible laisse le temps de mettre à jour les consommateurs.' ),
                    $this->mc('Une tentative de connexion échoue. Quel équilibre doit viser le message public ?', 'Être utile sans révéler si le compte existe ni exposer de détails internes', 'Afficher le hachage stocké', 'Préciser le mot de passe attendu', 'Retourner la pile d’appel complète', 'Des messages trop précis peuvent faciliter l’énumération de comptes ou divulguer des détails.' ),
                ],
