            [
                'title' => 'Livrer des changements avec maîtrise',
                'description' => 'Planifier tests, migrations, déploiements progressifs et observation après mise en production.',
                'difficulty' => 'Professional',
                'questions' => [
                    $this->mc('Une pipeline de production échoue sur un test après fusion. Quelle action est la plus professionnelle ?', 'Bloquer la promotion, diagnostiquer le test et corriger ou annuler le changement selon le risque', 'Ignorer le test parce que le code compile', 'Désactiver la pipeline définitivement', 'Déployer d’abord pour voir si les utilisateurs s’en plaignent', 'Un échec automatisé est un signal à qualifier avant exposition en production.' ),
                    $this->mc('Une nouvelle version est activée d’abord pour 5 % des utilisateurs. Quel mécanisme permet ce ciblage progressif ?', 'Un déploiement canari ou un feature flag contrôlé', 'Un renommage du dépôt', 'Une migration SQL sans suivi', 'Un cache sans expiration', 'Canari et flags permettent d’observer un sous-ensemble avant généralisation.' ),
                    $this->mc('Les indicateurs d’erreur augmentent pour la version canari. Quelle décision limite l’impact ?', 'Arrêter ou inverser l’exposition et investiguer avant d’élargir', 'Augmenter la part d’utilisateurs', 'Désactiver les alertes', 'Supprimer les logs du canari', 'Une hausse anormale doit stopper la progression et activer le plan de retour.' ),
                    $this->mc('Une migration modifie le schéma et le code dans un seul déploiement avec arrêt complet. Quelle stratégie améliore la réversibilité ?', 'Déployer une évolution additive compatible, migrer les données puis retirer l’ancien schéma ultérieurement', 'Supprimer l’ancien champ avant le code', 'Modifier la production à la main pendant le trafic', 'Ignorer la compatibilité des versions', 'Une évolution additive permet une coexistence temporaire et des étapes de rollback plus sûres.' ),
